local MournChapterEntryDialog = Class("MournChapterEntryDialog")
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')
local ChapterEntryCell = "Game.Activity.Mourn.Cell.MournChapterEntryCell"

function MournChapterEntryDialog:__init()

end

function MournChapterEntryDialog:__delete()
	self.controller = nil
end

function MournChapterEntryDialog:Awake()
	--self:AddUIClick()
end

function MournChapterEntryDialog:AddUIClick()

end

function MournChapterEntryDialog:OnFocus(focus)

end

function MournChapterEntryDialog:OnShow()
	self.chapterData = ActivityMournUtils.GetChapterInfo()
	self:RefreshLoopLostView()
end

function MournChapterEntryDialog:RefreshLoopLostView()
	local count = table.count(self.chapterData)
	if not self.LoopList.IsListViewInit then
		self.LoopList:InitListView(count, Bind(self, self.OnGetItemByIndex))
	else
		GameUtils.ReloadData(self.LoopList, count)
	end
	
	local index = ActivityMournUtils.GetCurQuestIndex()
	self:SetCirclePos(index)
	if index > 1 and index < table.count(self.chapterData)  then
		index = index - 1
	end
	self.LoopList:MovePanelToItemIndex(index - 1)
end

function MournChapterEntryDialog:OnGetItemByIndex(loopListView, index)
	if index < 0 then
		return nil
	end
	local index = index + 1
	local cell = loopListView:NewListViewItem("MournChapterCell")
	if not isNull(cell) then
		local env = CfUtils.GetLuaScr(cell, ChapterEntryCell)
		if not isNull(env) then
			env:SetCallBack(Bind(self,self.OnChapterNodeClick))
			env:RefreshShow(self.chapterData[index], index)
		end
	end
	return cell
end

function MournChapterEntryDialog:OnChapterNodeClick()
	CfUtils.SetActive(self.ImgMaskBlack_Mask.gameObject,false)
end

function MournChapterEntryDialog:SetCirclePos(index)
	if index == 1 then
		self.ImgMaskBlack_Mask.transform.localPosition = Vector3(-506,0,0)
	elseif index == table.count(self.chapterData) then
		self.ImgMaskBlack_Mask.transform.localPosition = Vector3(579,0,0)
	else
		self.ImgMaskBlack_Mask.transform.localPosition = Vector3(0,0,0)
	end
end

function MournChapterEntryDialog:OnInitialize()

end

function MournChapterEntryDialog:OnFinalize()
	self.controller = nil --删除lua层引⽤用到的c#对象
	self:Delete()
end
return MournChapterEntryDialog